import json,pathlib,datetime
p=pathlib.Path(__file__).parent
d=json.loads((p/'dag.json').read_text());before=json.loads(json.dumps(d)); ns={n['id']:n for n in d['nodes']}
aurl='https://www.anthropic.com/research/demystifying-evals-for-ai-agents';ourl='https://developers.openai.com/api/docs/guides/evaluation-best-practices'
def ev(url,loc,claim):return {'url':url,'locator':loc,'claim':claim,'access':'supplemental web page, relevant passages read'}
def new(i,q,a,e,status='supported',basis=None):
 n=dict(id=i,question=q,answer=a,status=status,evidence=e)
 if basis:n['claim_type']=basis
 d['nodes'].append(n);ns[i]=n
new('tool','What is a tool in this application?','A tool is a Python-like function the application can call to obtain information or change external records. The model can request a function and arguments; the application executes it and returns its result.',[ev(ourl,'Single-agent architectures, lines 1102-1123','Tools are developer functions; selection and arguments require evaluation.')])
ns['application']['answer']='The tested application includes the model call, its instructions, the information supplied to it, and any tool execution. Save which version of each component was used: a model score alone does not describe this combined behavior.'
ns['application']['evidence'].append(ev(aurl,'The structure of an evaluation, line 67','Evaluate model and surrounding software together.'));ns['application']['status']='supported'
ns['objective']['status']='supported';ns['objective']['claim_type']='Source-supported method with explicitly constructed support requirements; confirm actual requirements with owner.'
ns['objective']['evidence'].append(ev(ourl,'Single-agent architectures, lines 1114-1123','Missing order ID prompts clarification; assess function and arguments.'))
ns['case']['status']='supported';ns['case']['claim_type']='Synthesis of supplied classification example, extended to full support context.'
ns['run']['status']='supported';ns['run']['claim_type']='Practical record schema synthesized from documented run inputs and results.'
ns['run']['answer']+=' For a conversation, retain earlier messages and intermediate function results, not just the last answer.'
ns['run']['evidence'].append(ev(aurl,'The structure of an evaluation, lines 61-66','A trial record includes interactions and tool results.'))
ns['aggregate']['status']='supported';ns['aggregate']['claim_type']='Arithmetic definition and scope inference from supplied best-practices guidance.'
new('repeatability','How can repeated attempts avoid changing the test itself?','Start each attempt with the case’s intended initial records and conversation state; leftover state can distort results.',[ev(aurl,'Design the eval harness and graders, Step 4, lines 305-307','Reset shared state between trials.')])
new('uncertainty','Why might a higher score fail to show a dependable improvement?','A changed score can reflect different generated answers or different selected cases. Repeated attempts probe answer variation; additional representative cases probe case coverage. Neither alone guarantees future performance.',[ev(aurl,'How to think about non-determinism, lines 271-282','Task success varies across attempts.'),ns['coverage']['evidence'][0]],basis='Synthesis; no formal significance test or required sample size claimed.')
new('heldout','Why reserve cases that were not used to choose the change?','Repeatedly choosing changes that fit the same examples can favor those examples. Keep some cases out of that selection process and evaluate the selected version on them. A held-out set still needs representative inputs and valid grading.',[ev(ourl,'Example: Summarizing transcripts, line 1029','Uses held-out reference cases.')],basis='Reasoned motivation for source’s held-out-set design; no statistical guarantee.')
ns['comparison']['answer']='Run the two identified application versions on the same cases with unchanged grading rules and equivalent starting state. Compare per-case gains and regressions, not just the average; inspect repeated attempts before interpreting a small gain. Reserve unused cases for the final comparison.'
ns['comparison']['status']='supported';ns['comparison']['claim_type']='Controlled comparison design synthesized from documented repeat evaluations, fixed data, and held-out examples.'
ns['comparison']['evidence']=[ns['run']['evidence'][0],ev(ourl,'Design your eval process, lines 1014-1033','Compare runs and continuously evaluate; held-out example.')]
ns['action_outcome']['answer']='Check resulting records as well as words. A reply claiming a refund succeeded does not establish a completed, authorized refund.'
ns['action_outcome']['status']='supported';ns['action_outcome']['evidence']=[ev(aurl,'The structure of an evaluation, line 65; Evaluating conversational agents, lines 219-257','Outcome is distinct from claimed completion; support example checks refund records.')]
new('decision','Does a high score mean the assistant is ready for customers?','No universal pass rate establishes readiness. Requirements determine which failures are acceptable. Inspect important failures separately: many correct policy answers cannot cancel out one unauthorized action. Evaluation evidence informs the owner’s decision; the tested cases do not cover every future situation.',[ns['aggregate']['evidence'][0],ns['objective']['evidence'][0]],basis='Decision guidance synthesized from task-specific objectives and limits of numerical scores; no prescribed release threshold.')
for i in ['start','target']:
 ns[i]['status']='supported';ns[i]['claim_type']='Synthesis of prerequisite claims';ns[i]['evidence']=[ns['objective']['evidence'][0],ns['run']['evidence'][0],ns['action_outcome']['evidence'][0]]
# Audit: edges removed when only order, motivation, or redundant self-contained wording.
remove={('application','variability'),('application','objective'),('calibration','aggregate'),('run','action_outcome'),('objective','start'),('reference','start'),('run','target')}
d['edges']=[e for e in d['edges'] if (e['from'],e['to']) not in remove]
adds=[('baseline','tool','Tools extend the reader’s known function input/output model to calls that retrieve or change records.'),('tool','application','The tested application includes tool execution, whose behavior must be understood.'),('tool','action_outcome','Resulting records distinguish effects of functions from the model’s words.'),('case','repeatability','Resetting requires the intended case-specific starting state.'),('run','uncertainty','Repeated attempts and case observations are the objects whose scores can vary.'),('case','heldout','A reserved set is a subset of reusable evaluation cases.'),('uncertainty','comparison','The comparison’s small-gain caveat depends on the two sources of variation.'),('repeatability','comparison','Equivalent starting state is required by the comparison design.'),('heldout','comparison','The final comparison reserves cases unused in choosing the change.'),('aggregate','decision','A high score is a summary with limited scope, not a readiness guarantee.'),('objective','decision','Acceptable failures and release conditions depend on the chosen requirements.'),('action_outcome','decision','The unauthorized-action example requires distinguishing actual actions from replies.'),('calibration','decision','Readiness evidence depends on grading the intended behavior, not only scoring consistently.'),('decision','start','The initial workflow must interpret its high average without treating it as a deployment guarantee.')]
d['edges'] += [dict(zip(['from','to','why'],x)) for x in adds]
# Make start’s actual necessary claims explicit and avoid making it a missing-prerequisite shortcut.
ns['start']['answer']='Start with one workflow, such as refund eligibility. Use the case, coverage and reference methods to prepare a small inspectable dataset. Execute and grade it using the run method, inspect failures, then compare revisions with the improvement method. Check real action outcomes when actions are enabled, and apply the decision limits before using scores to justify release.'
for x in [('reference','start','Preparing the starter dataset uses expert-checked expected behavior.'),('run','start','The starter workflow explicitly executes cases and grades saved outputs.')]:d['edges'].append(dict(zip(['from','to','why'],x)))
revision={'round':1,'timestamp':datetime.datetime.now(datetime.timezone.utc).isoformat(),'stage':'supplemental research repair','sources_opened':[ourl,aurl],'searches':['In-page: hold (no match), test set (no match), customer, compare, dataset, isolated, 20'],'changes':'Added tool, repeatability, uncertainty, heldout, decision; located outcome and application evidence; tightened dependency edges; resolved partial/gap statuses with explicit synthesis labels.','snapshot':'dag.round1.json'}
d['revisions'].append(revision)
(p/'dag.json').write_text(json.dumps(d,indent=2)+'\n');(p/'dag.round1.json').write_text(json.dumps(d,indent=2)+'\n')
with (p/'history.jsonl').open('a') as f:f.write(json.dumps({**revision,'event':'research_and_graph_revision','before':'dag.initial.json','after':'dag.round1.json','removed_edges':[list(x) for x in sorted(remove)],'added_nodes':['tool','repeatability','uncertainty','heldout','decision']})+'\n')
print(len(d['nodes']),len(d['edges']))
